fixture.setup:
mkdir -p fixture/src/components fixture/src/utils && cd fixture && git init && git config user.email 'test@test.com' && git config user.name 'Test' && cat > src/components/FeatureToggle.jsx << 'EOF'
export function FeatureToggle({ feature, children }) {
  const flags = useFeatureFlags();
  if (!flags[feature]) return null;
  return children;
}
EOF
cat > src/components/Button.jsx << 'EOF'
export function Button({ children, onClick }) {
  return <button onClick={onClick}>{children}</button>;
}
EOF
cat > src/utils/feature-flags.js << 'EOF'
export function useFeatureFlags() {
  return { newDashboard: true, betaAPI: false };
}
EOF
cat > src/utils/api.js << 'EOF'
export async function fetchData() {}
EOF
cat > package.json << 'EOF'
{
  "name": "git-op-fixture",
  "version": "1.0.0",
  "type": "module"
}
EOF
cd fixture && git add . && git commit -m 'Initial commit'
# Create unrelated dirty files
echo 'console.log("debug")' > debug-temp.js
echo 'temp config' > config.local.json
